})
rows = selected ? core.countryYears(data, selected.iso) : []
observed = rows.filter(d =&gt; d.applications != null || d.decisions != null)
outcomeRows = rows.flatMap(d =&gt; core.outcomes
  .filter(([key]) =&gt; d[key] != null)
